Widget originalWorkspaceField(TextEditingController controller) => TextFormField(
  controller: controller,
  maxLength: 60,
  decoration: const InputDecoration(
    labelText: 'Workspace name',
    helperText: 'Use a name your teammates recognize.',
  ),
  validator: (value) => (value == null || value.trim().isEmpty)
    ? 'Enter a workspace name.' : null,
);
